const ACADEMY_PROGRESS='scholarion-core-academy-v1';
let academyProgress;try{academyProgress=JSON.parse(localStorage.getItem(ACADEMY_PROGRESS))||{};}catch{academyProgress={};}
let academyLabCsv='';
const academyProgram=id=>academyPrograms.find(p=>p.id===Number(id));
const academyStaff=()=>['admin','faculty'].includes(model.role);
function academySave(){try{localStorage.setItem(ACADEMY_PROGRESS,JSON.stringify(academyProgress));}catch{toast('Local storage unavailable; keep a copy of your work.');}}
function moduleProgress(m){return academyProgress[m.id]||{};}
function moduleUnlocked(p,m){return academyStaff()||!m.prerequisite||academyProgress[m.prerequisite]?.complete;}
function academyLink(label,url){return `<a class="button secondary" href="${url}" download>${label}</a>`;}
function academyIndex(){return heading('Scholarion Academy · Core programs','Eleven draft teaching packages, connected to practice and badge artwork.')+`<div class="callout">Academic review edition. Offline rules simulations are available now. Live AI labs, recorded media, official assessments and hosted integrations remain pending.</div><div class="course-grid">${academyPrograms.map(p=>`<article class="card prose"><span class="tag">Program ${p.id} · Draft</span><h2>${esc(p.title)}</h2><p>${p.modules.length} modules · ${esc(p.length)} · ${esc(p.weeklyHours)} hours/week</p><p>${esc(p.summary)}</p>${btn('Open program','#academy/'+p.id)} ${academyLink('Student package',`academy/program-${p.id}/student-package.zip`)}</article>`).join('')}</div>`;}
function academyOverview(p){return `<div class="breadcrumbs"><a href="#academy">Core programs</a> / Program ${p.id}</div>`+heading(p.title,p.status,`<button class="button secondary" data-academy-badge="${p.id}">Create badge</button>`)+`<div class="two-col"><section class="card prose"><h2>Program syllabus</h2><p>${esc(p.summary)}</p><p><b>Audience:</b> Learners supporting ${esc(p.audience)}.</p><p><b>Prerequisites:</b> ${esc(p.prerequisites)}</p><p><b>Workload:</b> ${esc(p.length)} · ${p.weeklyHours} hours/week</p><p>${esc(p.delivery)}</p><div class="callout">${esc(p.scheduleNote)}</div><h3>Five competencies</h3>${listHTML(p.outcomes)}<h3>Course blocks</h3>${listHTML(p.blocks.map(b=>`${b.id}: modules ${b.modules[0]}–${b.modules.at(-1)} · ${b.status}`))}<h3>Proposed transfer</h3><p>${esc(p.transferPolicy)}</p></section><aside class="card prose"><h2>Program resources</h2><div class="academy-downloads">${academyLink('Download student package',`academy/program-${p.id}/student-package.zip`)}${academyLink('Program badge SVG',`academy/program-${p.id}/program-badge.svg`)}${academyLink('Capstone skill badge SVG',`academy/program-${p.id}/capstone-badge.svg`)}</div><p>Badge files are unsigned artwork. Official issuance remains blocked.</p><h3>Credential requirements</h3><p>${esc(p.credential.rule)}</p><details><summary>Historical source proposal</summary><p>${esc(p.credential.sourceDraftRules)}</p></details><h3>Proposed career support</h3>${listHTML(p.career.services)}<p>${esc(p.career.resumePrompt)}</p><p>${esc(p.career.disclaimer)}</p>${btn('Assessment briefs','#academy-assessments/'+p.id,true)} ${btn('Capstone','#academy-capstone/'+p.id,true)} ${btn('Quality gates','#academy-review/'+p.id,true)}</aside></div><section class="card"><h2>Learning modules</h2><p>Sequential learner checkpoints are saved on this browser. Staff can preview all modules. These checkpoints are not official grades.</p>${p.modules.map(m=>{const open=moduleUnlocked(p,m),done=moduleProgress(m).complete;return `<div class="module-row"><span class="module-number">${m.number}</span><div><h3>${esc(m.title)}</h3><p>Proposed week ${m.proposedWeek} · ${done?'Practice checkpoint complete':open?'Ready to study':'Complete previous module checkpoint first'}</p></div>${open?btn('Open','#academy-module/'+p.id+'/'+m.number,true):'<span class="tag">Locked</span>'}</div>`}).join('')}</section>`;}
let academyQuiz=null;
function quizFor(m){if(!academyQuiz||academyQuiz.id!==m.id){const pool=[...m.quiz].sort(()=>Math.random()-.5).slice(0,2);academyQuiz={id:m.id,questions:pool.map(q=>({...q,options:q.choices.map((text,i)=>({text,correct:i===q.correct})).sort(()=>Math.random()-.5)}))};}return academyQuiz;}
function academyModule(p,m){if(!moduleUnlocked(p,m))return heading('Module checkpoint locked','Complete the previous module practice checkpoint first.',btn('Back to program','#academy/'+p.id));const quiz=quizFor(m);const pr=moduleProgress(m);return `<div class="breadcrumbs"><a href="#academy/${p.id}">Program ${p.id}</a> / Module ${m.number}</div>`+heading(m.title,'Draft lesson · '+m.id)+`<div class="academy-module-grid"><article class="card prose"><span class="tag">${m.outcomes.join(' · ')}</span><h2>Learn</h2><p>${esc(m.lesson)}</p><div class="callout">${esc(m.activity.overview)}</div><h3>Objective</h3><p>${esc(m.activity.objective)}</p>${m.activity.steps.map(s=>`<h3>${esc(s.title)}</h3><p>${esc(s.text)}</p>`).join('')}<h3>Reflection</h3>${listHTML(m.activity.reflection)}<h3>Submission guidance</h3><p>${esc(m.activity.submission)}</p><p>${esc(m.activity.integrity)}</p><form id="academy-reflection" data-module="${m.id}"><label>Your practice reflection<textarea name="reflection" rows="4" maxlength="3000" required>${esc(pr.reflection||'')}</textarea></label><button class="button">Save reflection</button></form><h3>Two mini labs</h3>${m.miniLabs.map((l,i)=>`<h4>${i+1}. ${esc(l.title)}</h4><p>${esc(l.task)}</p>${academyLink('Starter notebook',m.path+'/mini-'+(i+1)+'-starter.ipynb')}`).join('')}<h3>Reading</h3><ul>${m.readings.map(r=>`<li><a href="${r.url}" target="_blank" rel="noopener">${esc(r.title)}</a></li>`).join('')}</ul></article><aside class="stack"><section class="card prose"><h2>Practice resources</h2>${[5,6,7,8,9].includes(p.id)?"<p>Use the visual lab for the no-code route. Python notebooks are optional instructor-supported extensions.</p>":""}<p>${esc(m.labTask)}</p><div class="academy-downloads">${academyLink('Student notebook',m.path+'/starter.ipynb')}${academyLink('Synthetic dataset',m.path+'/dataset.csv')}${academyLink('Larger assignment dataset',m.path+'/assignment-dataset.csv')}${academyLink('Data card',m.path+'/data-card.json')}${academyLink('Activity worksheet',m.path+'/activity.md')}${academyLink('Visual walkthrough',m.path+'/walkthrough.md')}<a class="button secondary" href="${m.path}/slides.html" target="_blank" rel="noopener">Open lesson slides</a>${academyLink('Lecture script',m.path+'/lecture-script.txt')}</div><p>Python 3.12.3, standard library only. Local solution cells executed; Colab and Cloud Lab have not been tested.</p>${btn('Visual workflow lab','#academy-lab/'+p.id+'/'+m.number)}</section><section class="card prose"><h2>Practice quiz</h2><p>Two randomized questions. Public practice explanations; not a secure graded examination.</p><form id="academy-quiz" data-program="${p.id}" data-module="${m.id}">${quiz.questions.map((q,i)=>`<fieldset><legend>${esc(q.prompt)}</legend>${q.options.map((o,j)=>`<label class="academy-answer"><input type="radio" name="q${i}" value="${j}" required> ${esc(o.text)}</label>`).join('')}</fieldset>`).join('')}<button class="button">Check practice answers</button></form><div id="academy-quiz-feedback" role="status">${pr.quizScore!==undefined?`Saved score: ${pr.quizScore}/2`:''}</div></section><section class="card prose"><h2>Module checkpoint</h2><p>Save a reflection and answer both practice questions correctly to unlock the next module.</p><button class="button" data-academy-complete="${m.id}" data-program="${p.id}">Complete practice checkpoint</button><p>${pr.complete?'Checkpoint complete.':'Not yet complete.'}</p></section><section class="card prose"><h2>Weekly announcement draft</h2><p>${esc(m.announcement)}</p><h3>Live session plan</h3><p>${esc(m.liveSession)}</p><h3>Remediation</h3><p>${esc(m.masteryPath.remediation)}</p><h3>Enrichment</h3><p>${esc(m.masteryPath.enrichment)}</p></section></aside></div>`;}
function academyAssessments(p){return heading('Assessment briefs',p.title,btn('Back to program','#academy/'+p.id,true))+`<p class="callout">Draft briefs and rubric; final exam authoring and academic validation remain pending. No submission or grade is issued here.</p>`+p.assessments.map(a=>`<details class="card prose"><summary>${esc(a.id)} · Module ${a.module}</summary><p>${esc(a.brief)}</p>${listHTML(a.steps)}<p>Outcomes: ${a.outcomes.join(', ')}</p><p>${esc(a.aiPolicy)}</p></details>`).join('')+academyRubric(p);}
function academyRubric(p){return `<section class="card prose"><h2>Analytic rubric · 100 points</h2>${p.rubric.map(r=>`<h3>${esc(r.criterion)} · ${r.points} points · ${r.outcome}</h3>${listHTML(Object.entries(r.bands).map(([a,b])=>a+': '+b))}`).join('')}</section>`;}
function academyCapstone(p){return heading('Capstone project',p.title,btn('Back to program','#academy/'+p.id,true))+`<section class="card prose"><h2>Brief</h2><p>${esc(p.capstonePackage.brief)}</p>${p.capstonePackage.milestones.map(m=>`<h3>${esc(m.name)}</h3><p>${esc(m.deliverable)}</p>`).join('')}<h3>Example architecture scaffold</h3><p>${esc(p.capstonePackage.exemplar)}</p><h3>Peer review</h3><p>${esc(p.capstonePackage.peerReview)}</p><h3>Interview practice</h3><p>${esc(p.career.interviewPrompt)}</p></section>`+academyRubric(p);}
function academyReview(p){return heading('Quality gates and source reconciliation',p.title,btn('Back to program','#academy/'+p.id,true))+`<section class="card prose"><h2>Publication remains blocked</h2><p>Do not equate generated files with a production-ready curriculum.</p>${listHTML(Object.entries(p.qualityGates).map(([a,b])=>a+': '+b))}<h3>Evaluation plan</h3>${listHTML([p.evaluationPlan.pre,p.evaluationPlan.post,...p.evaluationPlan.survey])}<h3>Instructor package</h3><p>Executed solution notebooks and instructor guides are saved outside the web server in site/instructor-packages/program-${p.id}. They are not served by this learner preview.</p><h3>Import format</h3><p>The student ZIP is a native content package. It is not a validated Common Cartridge. Cloud Lab, LTI, media captions and licensed no-code platform builds remain pending.</p></section>`;}
function academyLab(p,m){if(!moduleUnlocked(p,m))return heading('Practice lab locked','Complete the preceding module checkpoint.',btn('Back','#academy/'+p.id));return heading('Visual workflow lab',m.title,btn('Back to module','#academy-module/'+p.id+'/'+m.number,true))+`<section class="card prose"><p>Reusable offline approval-flow simulation. This does not run a trained model, perform a transaction or replace the topic-specific notebook task.</p><p><b>Module task:</b> ${esc(m.labTask)}</p><form id="academy-lab-form" data-family="${m.family}">${m.family==='retrieval'?'<label>Evidence query<input name="query" value="approval required" required></label>':''}<label>Review threshold (0–1)<input name="threshold" type="number" min="0" max="1" step="0.1" value="0.8" required></label><button class="button">Run synthetic cases</button></form><div id="academy-lab-output" aria-live="polite"></div></section>`;}
const beforeAcademyRender=render;render=function(){const [route,id,num]=location.hash.slice(1).split('/');let body;const p=academyProgram(id);if(route==='academy')body=p?academyOverview(p):academyIndex();if(route.startsWith('academy-')){if(!p)body=heading('Program unavailable','Choose a core program.',btn('Core programs','#academy'));else if(route==='academy-assessments')body=academyAssessments(p);else if(route==='academy-capstone')body=academyCapstone(p);else if(route==='academy-review')body=academyReview(p);else{const m=p.modules[Number(num)-1];body=m?(route==='academy-lab'?academyLab(p,m):academyModule(p,m)):heading('Module unavailable','Choose a listed module.',btn('Back','#academy/'+p.id));}}if(body!==undefined){document.getElementById('app').innerHTML=integratedShell(route,body,model.role);decorateRole(model.role);bind();document.title='Scholarion Academy · Core learning';}else beforeAcademyRender();const nav=document.querySelector('.sidebar nav');if(nav)nav.insertAdjacentHTML('beforeend',`<a class="nav-item" href="#academy">${icon('book')}Core programs</a>`);if(route==='program'&&p)document.querySelector('#main').insertAdjacentHTML('afterbegin',`<div class="callout">Draft teaching package available. ${btn('Open modules and resources','#academy/'+p.id)}</div>`);if(route==='catalog')document.querySelector('#main').insertAdjacentHTML('afterbegin',`<p>${btn('Explore the 11 core teaching packages','#academy')}</p>`);};
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='academy-reflection'){e.preventDefault();academyProgress[f.dataset.module]={...academyProgress[f.dataset.module],reflection:new FormData(f).get('reflection')};academySave();toast('Reflection saved on this browser.');}if(f.id==='academy-quiz'){e.preventDefault();if(academyQuiz?.id!==f.dataset.module)return;const values=new FormData(f);let score=0;const feedback=academyQuiz.questions.map((q,i)=>{const option=q.options[Number(values.get('q'+i))];if(option?.correct)score++;return `<p><b>${option?.correct?'Correct':'Review needed'}</b> — ${esc(q.explanation)}</p>`;});academyProgress[f.dataset.module]={...academyProgress[f.dataset.module],quizScore:score};academySave();document.getElementById('academy-quiz-feedback').innerHTML=`<h3>${score}/2</h3>`+feedback.join('');}if(f.id==='academy-lab-form'){e.preventDefault();const threshold=Number(new FormData(f).get('threshold'));if(!Number.isFinite(threshold)||threshold<0||threshold>1)return;const rows=Array.from({length:18},(_,i)=>({id:'R'+String(i).padStart(3,'0'),queue:['North','South','Central'][i%3],score:i%7===0?null:(i%10)/10,expected:100+i*7,observed:100+i*7+(i%5===0?3:0)}));let headers=['Synthetic ID','Score','Next state'],data=rows.map(r=>[r.id,r.score??'Missing',r.score===null?'Needs data':r.score<threshold?'Human review':'Awaiting approval']);const family=f.dataset.family;if(family==='retrieval'){const docs=[['D1','human approval required before action'],['D2','weekly aggregate counts only'],['D3','approval required for sensitive update']];const query=new Set(String(new FormData(f).get('query')).toLowerCase().match(/[a-z]+/g)||[]);headers=['Source','Text','Token overlap'];data=docs.map(([id,text])=>[id,text,[...new Set(text.split(' '))].filter(w=>query.has(w)).length]).filter(r=>r[2]>0).sort((a,b)=>b[2]-a[2]||a[0].localeCompare(b[0]));}if(family==='quality'){headers=['Synthetic ID','Confidence','Validation'];data=rows.map(r=>[r.id,r.score??'Missing',r.score===null?'Rejected: missing confidence':'Valid numeric score']);}if(family==='reconcile'){headers=['Synthetic ID','Expected','Observed','Review'];data=rows.map(r=>[r.id,r.expected,r.observed,Math.abs(r.expected-r.observed)>.01?'Exception':'Within tolerance']);}if(family==='cost'){const assisted=rows.reduce((n,r)=>n+2+(r.score===null||r.score<threshold?7:1),0);headers=['Baseline minutes','Assisted and review minutes','Net saved'];data=[[rows.length*8,assisted,rows.length*8-assisted]];}if(family==='evaluation'){headers=['Queue','Review count','Total','Rate'];data=['North','South','Central'].map(q=>{const xs=rows.filter(r=>r.queue===q),n=xs.filter(r=>r.score===null||r.score<threshold).length;return [q,n,xs.length,(n/xs.length).toFixed(3)];});}academyLabCsv=[headers,...data].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');document.getElementById('academy-lab-output').innerHTML='<div class="table-scroll"><table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+data.map(r=>'<tr>'+r.map(v=>'<td>'+esc(String(v))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p>'+(data.length?'Synthetic simulation only. No actions executed.':'No supporting source found. Abstain rather than invent evidence.')+'</p><button class="button secondary" data-academy-export="result">Export result table</button>';}});
document.addEventListener('click',e=>{const badge=e.target.closest('[data-academy-badge]');if(badge){const p=academyProgram(badge.dataset.academyBadge);badgeConfig={id:p.id,title:p.title,type:'Certificate',style:'ribbon'};location.hash='badge-generator';return;}const t=e.target.closest('[data-academy-complete],[data-academy-export]');if(!t)return;if(t.dataset.academyComplete){const key=t.dataset.academyComplete,pr=academyProgress[key]||{};if(!pr.reflection?.trim()||pr.quizScore!==2)return toast('Save a reflection and score 2/2 on the practice quiz first.');academyProgress[key]={...pr,complete:true};academySave();render();toast('Practice checkpoint completed.');}if(t.dataset.academyExport){download('synthetic-lab-results.csv',academyLabCsv,'text/csv');}});
render();

